import {seed,age,assess,priority,decide,statusLabels,TODAY} from './domain.js';
const $=s=>document.querySelector(s);const money=n=>'₹'+n.toLocaleString('en-IN');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='arasu-demo-v1';let records;try{const v=JSON.parse(localStorage.getItem(KEY));records=Array.isArray(v)&&v.length===12&&v.every(a=>a.docs&&a.history&&statusLabels[a.status])?v:seed();}catch{records=seed();}
let view='pending',filter='all',query='',selected=records.find(a=>a.status==='pending')?.id||records[0].id,tab='overview',action='';
function persist(next){localStorage.setItem(KEY,JSON.stringify(next));records=next;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
const icon={grid:'▦',files:'▤',history:'◷',help:'?',arrow:'↗',search:'⌕'};
function render(){if(sessionStorage.getItem('arasu-demo-session')!=='officer'){login();return;}const pending=records.filter(a=>a.status==='pending'),done=records.length-pending.length;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="அரசு முகப்பு"><span class="brand-icon">அ</span><span>அரசு<small>அலுவலர் பணித்தளம்</small></span></a><div class="office"><span class="office-icon">⌂</span><div>வருவாய்த் துறை<small>மதுரை தெற்கு வட்டம்</small></div></div><div class="nav-label">பணியிடம்</div><nav><button data-view="pending" class="${view==='pending'?'active':''}"><span>▦</span> விண்ணப்பங்கள் <b>${pending.length}</b></button><button data-view="history" class="${view==='history'?'active':''}"><span>◷</span> முடிவு வரலாறு <b>${done}</b></button><button data-view="guide" class="${view==='guide'?'active':''}"><span>⊙</span> ஆய்வு வழிகாட்டி</button></nav><div class="sidebar-note"><span class="spark">✧</span><b>உதவி தொழில்நுட்பத்திடம்.<br>இறுதி முடிவு உங்களிடம்.</b><p>ஒவ்வொரு பரிந்துரையையும் சரிபார்த்த பின் முடிவெடுக்கவும்.</p></div><div class="profile"><span class="avatar">த</span><div>அ. தமிழ்ச்செல்வி<small>வருவாய் ஆய்வாளர் · மாதிரி</small><button id="logout" class="logout">வெளியேறு ↗</button></div></div></aside><main><header><div class="breadcrumb">பணியிடம் <span>/</span> வருமானச் சான்றிதழ்</div><div class="header-right"><span class="demo-dot"></span> மாதிரி பணித்தளம் <span class="date">28 அக்டோபர் 2026</span></div></header><div class="page"><div class="title-row"><div class="title"><div class="eyebrow">REV–103 · வருமானச் சான்றிதழ்</div><h1>${view==='history'?'முடிவு வரலாறு':view==='guide'?'ஆய்வு வழிகாட்டி':'ஒவ்வொரு விண்ணப்பமும், ஒரு முன்னேற்றம்.'}</h1><p>வணக்கம், தமிழ்ச்செல்வி. ${view==='pending'?'இன்றைய பணிகளைத் தெளிவாகத் தொடங்குங்கள்.':'உங்கள் ஆய்விற்கான வெளிப்படையான பதிவுகள்.'}</p></div><button class="secondary" id="export">↓ பதிவிறக்கு</button></div><div class="stats"><button data-filter="all" class="stat"><span>ஆய்வில் உள்ளவை <span class="stat-icon">▤</span></span><strong>${pending.length}<small>விண்ணப்பங்கள்</small></strong><div class="stat-foot">உங்கள் முடிவிற்காகக் காத்திருக்கின்றன</div></button><button data-filter="overdue" class="stat overdue"><span>முதலில் கவனிக்கவும் <span class="stat-icon">◷</span></span><strong>${pending.filter(a=>age(a)>=15).length}<small>விண்ணப்பங்கள்</small></strong><div class="stat-foot"><i></i> 15 நாட்கள் அல்லது அதற்கு மேல்</div></button><button data-filter="attention" class="stat"><span>விளக்கம் தேவை <span class="stat-icon">⚑</span></span><strong>${pending.filter(a=>assess(a).issues.length).length}<small>விண்ணப்பங்கள்</small></strong><div class="stat-foot">ஆவணக் குறைவு / தகவல் முரண்பாடு</div></button><button data-view="history" class="stat"><span>முடிவு செய்யப்பட்டவை <span class="stat-icon">✓</span></span><strong>${done}<small>/ ${records.length}</small></strong><div class="progress"><i style="width:${done/records.length*100}%"></i></div></button></div>${view==='guide'?guide():view==='history'?history():workspace()}</div><footer><span>அரசு · அலுவலருக்கான எளிய பணித்தளம்</span><span>கற்பனைத் தரவுகள் மட்டுமே · அரசு அதிகாரப்பூர்வத் தளம் அல்ல</span></footer></main>`;bind();}
function workspace(){let list=records.filter(a=>a.status==='pending'&&(filter==='all'||filter==='overdue'&&age(a)>=15||filter==='attention'&&assess(a).issues.length||filter==='ready'&&!assess(a).issues.length)&&(a.name+' '+a.id+' '+a.village).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>age(b)-age(a));if(!list.some(a=>a.id===selected))selected=list[0]?.id;let a=records.find(a=>a.id===selected);return `<section class="workspace"><div class="queue"><div class="queue-head"><h2>விண்ணப்பப் பட்டியல் <span>${list.length}</span></h2><span class="sort">பழையவை முதலில் ↓</span></div><label class="search"><span>⌕</span><input id="search" value="${esc(query)}" placeholder="பெயர், எண் அல்லது ஊர்…" aria-label="விண்ணப்பத்தைத் தேடு"><kbd>தேடு</kbd></label><div class="filters">${[['all','அனைத்தும்'],['overdue','முன்னுரிமை'],['attention','கவனம் தேவை'],['ready','தயார்']].map(([k,v])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${v}</button>`).join('')}</div><div class="application-list">${list.map(r=>`<button class="application ${selected===r.id?'chosen':''}" data-select="${r.id}"><div class="application-top"><span class="record-id">${r.id}</span><span class="age ${age(r)>=15?'late':''}">${age(r)} நாட்கள்</span></div><div class="applicant-line"><span class="person-avatar">${r.name.slice(0,1)}</span><div><h3>${r.name}</h3><p>${r.village} <span>·</span> ${r.members} உறுப்பினர்கள்</p></div><span class="chevron">›</span></div><div class="application-bottom"><span class="badge ${age(r)>=15?'amber':assess(r).issues.length?'rose':'green'}">${age(r)>=15?'◷ முன்னுரிமை':assess(r).issues.length?'⚑ கவனம் தேவை':'✓ ஆய்விற்குத் தயார்'}</span><span>${money(r.income)} / ஆண்டு</span></div></button>`).join('')||'<div class="empty"><span>✓</span><h3>விண்ணப்பங்கள் இல்லை</h3><p>வேறு வடிகட்டியைத் தேர்ந்தெடுக்கவும்.</p></div>'}</div><div class="queue-footer">மாதிரி தேதி: 28.10.2026 · 15 நாள் முன்னுரிமை விதி</div></div><div class="detail">${a?detail(a):'<div class="empty"><h2>பணி முடிந்தது</h2><p>இந்தப் பட்டியலில் விண்ணப்பங்கள் இல்லை.</p></div>'}</div></section>`;}
function detail(a){const ai=assess(a);return `<div class="detail-head"><div><div class="record-id">${a.id}</div><h2>${a.name}</h2><p>${a.village} · மதுரை தெற்கு</p></div><span class="badge neutral">● ஆய்வில் உள்ளது</span></div><div class="tabs">${[['overview','விண்ணப்ப விவரம்'],['documents',`ஆவணங்கள் (${a.docs.filter(d=>d.present).length}/${a.docs.length})`],['timeline','நடவடிக்கைகள்']].map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div><div class="detail-body">${tab==='overview'?`<div class="info-grid"><div><label>ஆண்டு வருமானம்</label><strong>${money(a.income)}</strong></div><div><label>விண்ணப்பித்த நாள்</label><strong>${a.submitted.split('-').reverse().join('.')}</strong></div><div><label>தொழில்</label><b>${a.occupation}</b></div><div><label>பயன்பாடு</label><b>${a.purpose}</b></div></div><div class="assistant"><div class="assistant-heading"><span class="ai-icon">✧</span><h3>AI ஆய்வு உதவி</h3><span class="ai-label">விதி அடிப்படையிலான மாதிரி</span></div><p class="summary">${a.name}, ${a.village} பகுதியைச் சேர்ந்தவர். ${a.members} பேர் கொண்ட குடும்பத்தின் ஆண்டு வருமானம் ${money(a.income)} எனத் தெரிவித்துள்ளார். ${a.purpose} பெறச் சான்றிதழ் கோரியுள்ளார்.</p><div class="check-heading">சரிபார்ப்பில் கண்டறிந்தவை</div>${ai.issues.length?ai.issues.map(s=>`<div class="finding warning"><span>!</span><p>${s}</p></div>`).join(''):'<div class="finding success"><span>✓</span><p>மாதிரி ஆவணங்கள் அனைத்தும் உள்ளன. வருமானத் தொகைகள் பொருந்துகின்றன.</p></div>'}<div class="recommendation"><span>பரிந்துரை</span><strong>${ai.suggestion==='returned'?'விளக்கம் கோரித் திருப்பலாம்':'ஒப்புதலுக்குப் பரிசீலிக்கலாம்'} ↗</strong><p>${ai.suggestion==='returned'?'குறைபாடுகளைத் தெளிவுபடுத்திய பின் மீண்டும் ஆய்வு செய்யவும்.':'அசல் ஆவணங்களின் நம்பகத்தன்மையை நேரடியாக உறுதிசெய்யவும்.'}</p></div><div class="ai-disclaimer">ⓘ மாதிரி தரவின் அடிப்படையிலான உதவி மட்டுமே. இறுதி முடிவு அலுவலருடையது.</div></div><button class="text-button" data-tab="documents">ஆதார ஆவணங்களைப் பார்க்கவும் →</button>`:tab==='documents'?`<div class="section-intro"><h3>இணைக்கப்பட்ட ஆவணங்கள்</h3><p>இவை கற்பனையான உரை மாதிரிகள். உண்மையான ஆவணங்கள் அல்ல.</p></div>${a.docs.map(d=>`<div class="doc-row"><span class="doc-icon">▤</span><div><b>${d.title}</b><small>${d.present?'உரை மாதிரி · கற்பனைத் தரவு':'இணைக்கப்படவில்லை'}</small></div>${d.present?`<button class="secondary" data-doc="${d.key}">பார் ↗</button>`:'<span class="badge rose">இல்லை</span>'}</div>`).join('')}`:`<div class="timeline"><span class="timeline-dot"></span><b>விண்ணப்பம் பெறப்பட்டது</b><p>${a.submitted} · மாதிரி இ-சேவை வரவு</p><p>அலுவலரின் ஆய்விற்காக ஒதுக்கப்பட்டது.</p></div><div class="timeline"><span class="timeline-dot pale"></span><b>ஆவண ஆய்வு நிலுவையில்</b><p>தானியங்கி உதவி எந்த முடிவையும் பதிவு செய்யாது.</p></div>`}</div><div class="decision-bar"><div><b>உங்கள் ஆய்வு. உங்கள் முடிவு.</b><small>காரணம் பதிவு செய்வது கட்டாயம்.</small></div><div class="decision-buttons"><button class="reject" data-action="rejected">நிராகரி</button><button class="secondary" data-action="returned">திருப்பி அனுப்பு</button><button class="primary" data-action="approved">✓ ஒப்புதல்</button></div></div>`;}
function history(){const all=records.filter(a=>a.status!=='pending');return `<section class="history-panel"><div class="panel-heading"><h2>பதிவு செய்யப்பட்ட முடிவுகள்</h2><button class="secondary" id="reset">மாதிரியை மீட்டமை</button></div><p>இந்த உலாவியில் மட்டும் சேமிக்கப்படும் மாதிரி பதிவுகள்.</p>${all.map(a=>{let h=a.history.at(-1);return `<article class="history-item"><div><span class="record-id">${a.id}</span><h3>${a.name}</h3><p>${esc(h.reason)}</p><small>${h.officer} · ${new Date(h.at).toLocaleString('ta-IN')}</small></div><span class="badge ${a.status==='approved'?'green':a.status==='returned'?'amber':'rose'}">${statusLabels[a.status]}</span></article>`;}).join('')||'<div class="empty"><span>◷</span><h3>இன்னும் முடிவுகள் இல்லை</h3><p>விண்ணப்பத்தை ஆய்வு செய்து முதல் முடிவைப் பதிவு செய்யவும்.</p></div>'}</section>`;}
function guide(){return `<section class="guide"><div class="eyebrow">வெளிப்படையான ஆய்வு</div><h2>மனித மேற்பார்வையுடன் ஒரு எளிய செயல்முறை</h2><ol><li><b>முன்னுரிமை அறியுங்கள்</b><p>15 நாட்கள் அல்லது அதற்கு மேல் காத்திருக்கும் விண்ணப்பங்கள் முதலில் காட்டப்படும். இது மாதிரி பணிவரிசை விதி; சட்டக் காலக்கெடு எனக் கருத வேண்டாம்.</p></li><li><b>ஆவணங்களை ஆய்வு செய்யுங்கள்</b><p>புகைப்படம், முகவரிச் சான்று, குடும்ப அட்டை, சுய உறுதிமொழி, வருமான ஆதாரம் ஆகியவற்றின் மாதிரி உரைகளைப் பாருங்கள். தொழில் சார்ந்த கூடுதல் ஆவணங்களை அலுவலர் தனியாகச் சரிபார்க்க வேண்டும்.</p></li><li><b>உதவிக் குறிப்பை மதிப்பிடுங்கள்</b><p>ஆவணம் இல்லாமை மற்றும் இரண்டு வருமானத் தொகைகளுக்கிடையிலான வேறுபாடு மட்டும் விதிகளால் கண்டறியப்படும். OCR அல்லது நேரடி AI இணைப்பு இல்லை. மோசடி அல்லது சட்டத் தகுதியை இது தீர்மானிக்காது.</p></li><li><b>காரணத்துடன் முடிவெடுங்கள்</b><p>ஒப்புதல், நிராகரிப்பு அல்லது திருப்பி அனுப்புதல்: ஒவ்வொரு முடிவிற்கும் காரணமும் அலுவலரின் உறுதிப்படுத்தலும் அவசியம். குறைபாடு மட்டும் நிராகரிப்பிற்கான தானியங்கி காரணம் அல்ல.</p></li></ol><a href="https://tnesevai.tn.gov.in/Pages/FAQ.aspx" target="_blank" rel="noreferrer">அதிகாரப்பூர்வ e-Sevai ஆவண வழிகாட்டி ↗</a><p>இது சுயாதீன செயல்விளக்கம். அரசு அமைப்புடன் இணைக்கப்படவில்லை.</p></section>`;}
function bind(){$('#logout').onclick=()=>{sessionStorage.removeItem('arasu-demo-session');render();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{view='pending';filter=b.dataset.filter;render();});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;tab='overview';render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});$('#search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>openDecision(b.dataset.action));document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>openDoc(b.dataset.doc));$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({demo:true,referenceDate:TODAY,applications:records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='arasu-demo-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('மாதிரி பதிவுகள் பதிவிறக்கப்பட்டன.');};$('#reset')?.addEventListener('click',()=>{if(confirm('அனைத்து மாதிரி முடிவுகளையும் அழித்து மீட்டமைக்கவா?')){try{persist(seed());view='pending';selected=records[0].id;render();toast('மாதிரி மீட்டமைக்கப்பட்டது.');}catch{toast('சேமிக்க இயலவில்லை. உலாவி சேமிப்பை அனுமதிக்கவும்.');}}});}
function openDecision(s){action=s;$('#decision-form').reset();$('#decision-title').textContent={approved:'ஒப்புதல் வழங்கவா?',returned:'திருப்பி அனுப்பவா?',rejected:'நிராகரிக்கவா?'}[s];$('#decision-description').textContent=`${records.find(a=>a.id===selected).name} · ${selected}. முடிவு இந்த உலாவியின் மாதிரி வரலாற்றில் பதிவாகும்.`;$('#decision').showModal();}
$('#cancel-decision').onclick=()=>$('#decision').close();$('#decision-form').onsubmit=e=>{e.preventDefault();try{let a=records.find(a=>a.id===selected);persist(records.map(r=>r.id===selected?decide(a,action,$('#reason').value,$('#verified').checked):r));$('#decision').close();render();toast('முடிவு காரணத்துடன் பதிவு செய்யப்பட்டது.');}catch(err){toast(err.message);}};
function openDoc(key){const a=records.find(a=>a.id===selected),d=a.docs.find(d=>d.key===key);$('#document-content').innerHTML=`<div class="eyebrow">கற்பனை ஆவணம் · ${a.id}</div><h2>${d.title}</h2><div class="sample-document"><div class="watermark">மாதிரி / SAMPLE</div><h3>${a.name}</h3><p>ஊர்: ${a.village}</p><p>${key==='income'?`ஆண்டு வருமானம்: ${money(a.evidenceIncome)}`:key==='family'?`குடும்ப உறுப்பினர்கள்: ${a.members}`:key==='declaration'?`தெரிவிக்கப்பட்ட ஆண்டு வருமானம்: ${money(a.income)}`:key==='address'?'முகவரி: மாதிரி தெரு, '+a.village+', மதுரை':'புகைப்படத்திற்கான மாதிரி இடம்'}</p><p>பதிவு: ${a.submitted}</p><hr><p>செயல்விளக்கத்திற்காக உருவாக்கப்பட்ட உரை. சரிபார்க்கப்பட்ட அரசு ஆவணம் அல்ல.</p></div>`;$('#document').showModal();}$('#close-document').onclick=()=>$('#document').close();
function login(){$('#app').innerHTML=`<div class="login-page"><div class="login-story"><a class="brand" href="#"><span class="brand-icon">அ</span><span>அரசு<small>அலுவலர் பணித்தளம்</small></span></a><div><div class="eyebrow">REV–103 · வருமானச் சான்றிதழ்</div><h1>தெளிவான ஆய்வு.<br>நம்பிக்கையான முடிவு.</h1><p>விண்ணப்பங்களைக் கவனமாக ஆய்வு செய்யவும்,<br>காரணங்களுடன் முடிவெடுக்கவும் ஒரு எளிய பணித்தளம்.</p><div class="login-features"><span>01 · முன்னுரிமைப் பட்டியல்</span><span>02 · ஆவண ஆய்வு உதவி</span><span>03 · அலுவலரின் இறுதி முடிவு</span></div></div><small>கற்பனைத் தரவுகள் மட்டுமே · அரசு அதிகாரப்பூர்வத் தளம் அல்ல</small></div><div class="login-form-wrap"><form id="login-form"><div class="eyebrow">மதுரை தெற்கு · வருவாய்த் துறை</div><h2>வணக்கம், அலுவலரே.</h2><p>மாதிரி பணித்தளத்தில் உள்நுழையவும்.</p><label for="email">மின்னஞ்சல்</label><input id="email" type="email" autocomplete="username" required value="officer@arasu.demo"><label for="password">கடவுச்சொல்</label><input id="password" type="password" autocomplete="current-password" required value="Demo@123"><p id="login-error" role="alert"></p><button class="primary" type="submit">பணித்தளத்திற்குச் செல் →</button><div class="demo-login"><b>சோதனைக்கான அணுகல்</b><p>officer@arasu.demo · Demo@123</p><small>இது செயல்விளக்க உள்நுழைவு மட்டுமே; பாதுகாப்பான அடையாளச் சரிபார்ப்பு அல்ல. தரவுகள் இந்த உலாவியில் மட்டுமே சேமிக்கப்படும்.</small></div></form></div></div>`;$('#login-form').onsubmit=e=>{e.preventDefault();if($('#email').value.trim()==='officer@arasu.demo'&&$('#password').value==='Demo@123'){sessionStorage.setItem('arasu-demo-session','officer');render();}else{$('#login-error').textContent='மின்னஞ்சல் அல்லது கடவுச்சொல் சரியில்லை.';}};}
render();
